function storyDefinitionPreview(body){var lines=String(body||'').replace(/\r/g,'').split('\n');var start=lines.findIndex(function(line){var heading=line.match(/^#{2,3}\s+(.+)/);return heading&&['definition',"qu'est-ce",'comprendre','concept','mecanisme','au-dela',"coup d'"].some(function(marker){return heading[1].normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’‘]/g,"'").includes(marker)})});if(start<0)return '';var paragraphs=[],paragraph=[];for(var i=start+1;i<lines.length;i++){var line=lines[i].trim();if(/^#{1,3}\s/.test(line))break;if(!line){if(paragraph.length){paragraphs.push(paragraph.join(' '));paragraph=[]}if(paragraphs.length>=3)break;continue}if(/^[-*]\s|^\d+\.\s/.test(line)){if(paragraph.length){paragraphs.push(paragraph.join(' '));paragraph=[]}break}paragraph.push(line)}if(paragraph.length)paragraphs.push(paragraph.join(' '));var text=paragraphs.join(' ').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/[*_\x60]/g,'').trim();var sentences=text.match(/[^.!?]+[.!?]+(?:[»”"']+)?|[^.!?]+$/g)||[];var preview=sentences.slice(0,3).map(function(sentence){return sentence.trim()}).join(' ');if(preview.length>450){preview=preview.slice(0,447).replace(/\s+\S*$/,'').trim()+'…'}return preview}
